from pathlib import Path
import ast, json, os

src = Path('/inputs')
out = Path('/work/layout.json')

# Read the required reference as inert UTF-8 text; do not interpret or execute it.
_ = (src / 'smell-catalog.md').read_text(encoding='utf-8')

paths = []
for p in src.iterdir():
    if not p.is_file() or p.suffix != '.py':
        continue
    n = p.name
    if n == '__init__.py' or n.startswith('test_') or n.endswith('_test.py'):
        continue
    paths.append(p)
paths.sort(key=lambda p: p.name)

included = {p.stem: p.name for p in paths}
line_counts = {}
graph = {}

for p in paths:
    text = p.read_text(encoding='utf-8')
    line_counts[p.name] = len(text.splitlines())
    tree = ast.parse(text, filename=str(p))
    targets = set()
    for node in ast.walk(tree):
        if isinstance(node, ast.Import):
            for alias in node.names:
                parts = alias.name.split('.')
                if len(parts) >= 3 and parts[0:2] == ['skillc', 'frontend']:
                    stem = parts[2]
                    if stem in included and stem != p.stem:
                        targets.add(included[stem])
        elif isinstance(node, ast.ImportFrom):
            if node.level == 1:
                if node.module:
                    stem = node.module.split('.')[0]
                    if stem in included and stem != p.stem:
                        targets.add(included[stem])
                else:
                    for alias in node.names:
                        if alias.name == '*':
                            continue
                        stem = alias.name.split('.')[0]
                        if stem in included and stem != p.stem:
                            targets.add(included[stem])
            elif node.level == 0:
                mod = node.module or ''
                parts = mod.split('.') if mod else []
                if len(parts) >= 3 and parts[0:2] == ['skillc', 'frontend']:
                    stem = parts[2]
                    if stem in included and stem != p.stem:
                        targets.add(included[stem])
                elif parts == ['skillc', 'frontend']:
                    for alias in node.names:
                        if alias.name == '*':
                            continue
                        stem = alias.name.split('.')[0]
                        if stem in included and stem != p.stem:
                            targets.add(included[stem])
    graph[p.name] = sorted(targets)

files = [
    {'name': p.name, 'lines': line_counts[p.name], 'imports': graph[p.name]}
    for p in paths
]

# Map every qualifying prefix to its member set, then collapse equal sets.
stems = sorted(included)
member_sets = set()
for stem in stems:
    for size in range(4, len(stem) + 1):
        prefix = stem[:size]
        members = frozenset(s for s in stems if s.startswith(prefix))
        if len(members) >= 3:
            member_sets.add(members)

def lcp(strings):
    vals = sorted(strings)
    a, b = vals[0], vals[-1]
    i = 0
    while i < min(len(a), len(b)) and a[i] == b[i]:
        i += 1
    return a[:i]

prefix_clusters = []
for members in member_sets:
    names = sorted(included[s] for s in members)
    prefix_clusters.append({
        'prefix': lcp(members),
        'files': names,
        'lines': sum(line_counts[n] for n in names),
    })
prefix_clusters.sort(key=lambda row: row['prefix'])

import_tree_clusters = []
for root in sorted(graph):
    if len(graph[root]) < 3:
        continue
    seen = set()
    stack = [root]
    while stack:
        name = stack.pop()
        if name in seen:
            continue
        seen.add(name)
        stack.extend(graph[name])
    if len(seen) >= 5:
        names = sorted(seen)
        import_tree_clusters.append({
            'root': root,
            'files': names,
            'lines': sum(line_counts[n] for n in names),
        })
import_tree_clusters.sort(key=lambda row: row['root'])

result = {
    'files': files,
    'prefix_clusters': prefix_clusters,
    'import_tree_clusters': import_tree_clusters,
}
out.write_text(json.dumps(result, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')
print('WROTE', out, out.stat().st_size)
print('FILES', len(files), 'PREFIX', len(prefix_clusters), 'TREES', len(import_tree_clusters))
print(out.read_text(encoding='utf-8'))

